// Modelos de la ruta general. Groq retira modelos sin aviso: si esta ruta
// empieza a devolver 404 o 'model_decommissioned', listar los vigentes con
//   curl -s -H "Authorization: Bearer $GROQ_API_KEY" https://api.groq.com/openai/v1/models
// y cambiarlos SOLO aca. No hay otro lugar donde esten escritos.
//
// NO usar groq/compound ni compound-mini aunque digan traer buscador web: medido
// el 12-09-2026, **casi nunca buscan** en el tier gratis — 4 de 5 preguntas de
// actualidad (incluido "a cuanto esta el dolar hoy") contestaron sin ejecutar
// ninguna herramienta, y la unica que intento buscar murio con HTTP 413
// "Request Entity Too Large" teniendo 66.264 de 70.000 tokens libres: al buscar
// mete el contenido de las paginas en el contexto y el tier gratis lo rechaza.
// Un buscador que no busca y ademas falla es peor que no tenerlo. La respuesta
// al dato desactualizado es que el modelo lo DECLARE — eso vive en el system
// prompt del nodo HTTP, no aca.
const GROQ_MODEL = 'openai/gpt-oss-120b';

const answer = (message) => [{ json: {
  mode: 'answer',
  payload: { kind: 'answer', message, sources: [], command_suggestion: '', command_context: '' }
}}];

// Una entrada invalida se RECHAZA con un answer explicito, no con throw: un
// throw corta el flujo antes del nodo Respond y n8n contesta 200 con cuerpo
// VACIO, que es el peor modo de falla (el bot lo puede mostrar como respuesta
// en blanco). Verificado el 12-09-2026. Rechazar no es degradar: no se ejecuta
// ninguna ruta y la ejecucion queda igual registrada en n8n.
const input = $json.body ?? $json;
const source = String(input.source ?? '').trim().toLowerCase();
const prompt = String(input.prompt ?? '').trim();
// El bot manda su perfil como DATO. No decide permisos —el bot intersecta la
// ruta con las suyas—, solo preferencias de ruta. Ver la rama tecnica.
const perfil = String(input.perfil ?? '').trim().toLowerCase();
// Perfiles cuyo TOML tiene `codex` en `rutas` (24-09-2026). Tiene que calzar con
// botv3/perfiles/*.toml; un desfase se degrada en el bot, no abre nada.
const PERFILES_CON_CODEX = new Set(['jaime']);
const allowed = new Set(['auto', 'sql', 'ha', 'gpt']);
if (!allowed.has(source)) return answer('Ruta no permitida. El router solo acepta auto, sql, ha o gpt.');
if (!prompt) return answer('La consulta llego vacia.');
if (prompt.length > 4000) return answer('La consulta supera el limite de 4000 caracteres.');

const pending = {
  sql: 'La ruta PostgreSQL esta clasificada, pero falta habilitar su catalogo de consultas SELECT.',
  ha: 'La ruta Home Assistant esta clasificada, pero falta habilitar el proxy de consultas GET.'
};

// El vocativo no es contenido: "Pilar, que hora es" no es una pregunta SOBRE
// Pilar. Se saca ANTES de clasificar, porque los nombres de los dos asistentes
// estan en PROPIO: sin esto, cada vez que Camila llama a su bot por el nombre
// la consulta se iria a la ruta claude, que para su perfil no lee archivos.
// Lenta y para nada, y en el caso mas frecuente de todos.
const text = prompt.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/^[\s\u00bf\u00a1"'\u00ab(-]*(hola|hey|oye|ok|buenas)?[\s,]*(pilar|jaime)\b[\s,:.!?\u00bf-]*/, '');
// El `\u00bf` de apertura NO es cosmetico y costo una consulta real (20-09-2026):
// `^\s*` no lo salta, asi que "\u00bfPilar, que peliculas hay?" conserva el vocativo,
// caza `pilar` en PROPIO y termina en la ruta claude. El canal donde pasa SIEMPRE
// es la voz: Whisper puntua lo que transcribe, o sea que cada nota de voz en que
// Camila llama a su bot por el nombre se iba a un agente sin archivos y sin
// buscador, a esperar 45 s para que le contestara que no tiene internet. Se saltan
// tambien comillas y parentesis de apertura, por el mismo motivo.

// Ruta explicita distinta de auto: se responde sin clasificar.
if (source !== 'auto') {
  if (source === 'gpt') return [{ json: { mode: 'groq', model: GROQ_MODEL, prompt } }];
  return answer(pending[source]);
}

// Un nombre de archivo con extension tecnica es una pregunta sobre el nodo aunque
// no traiga ninguna palabra clave: "que hace respaldo.sh" se iba a `gpt` —Groq
// opinando sobre un archivo que no puede ver— el 24-09-2026. Se exige el punto
// pegado a un nombre, asi "sh" o "md" sueltos no cazan.
const ARCHIVO = /\b[a-z0-9_@-]+\.(sh|py|mjs|js|ts|json|toml|ya?ml|conf|service|timer|path|mount|env|sql|ini|cfg|log|csv|md|gs|ps1)\b/;
// Palabras de Calendar y Gmail. `inbox` NO va: en este nodo es la carpeta de
// capturas del vault, no la bandeja de Gmail.
const AGENDA_CORREO = /\b(agenda|agendar|agendame|agendalo|agendala|calendario|evento|eventos|reunion|reuniones|cita|citas|correo|correos|mail|mails|email|emails|gmail|borrador|borradores|bandeja de entrada)\b/;
let route;
// `temperatura` tambien vive en las preguntas de clima, y esta rama corre ANTES
// que NECESITA_WEB: sin la guarda, "que temperatura va a hacer manana" termina
// en Home Assistant. Si la frase trae marca de afuera o de futuro no es el sensor
// del living. "que temperatura hay en el living" sigue yendo a ha.
const CLIMA_AFUERA = /\b(clima|pronostico|llover|lluvia|afuera|manana)\b/;
if (!CLIMA_AFUERA.test(text) && /\b(home assistant|sensor|sensores|temperatura|humedad|riego|domotica|entidad|entidades|huerto)\b/.test(text)) {
  route = 'ha';
} else if (/\b(postgres|postgresql|base de datos|tabla|tablas|registro(?! civil)|registros|filas?|consulta sql|tarifa|tarifas)\b/.test(text) || /\b(cuantos?|promedio|sumar|total)\b.*\b(datos|registros|filas|tarifas)\b/.test(text)) {
  route = 'sql';
} else if (/\b(chatgpt|openai|gpt|groq)\b/.test(text)) {
  route = 'gpt';
} else if (AGENDA_CORREO.test(text)) {
  // Agenda y correo (24-09-2026): la resuelve el bot hablando con google-puente.
  // Va ANTES que PROPIO y que NECESITA_WEB: "mi agenda de manana" trae posesivo y
  // trae "manana", y no es ni el vault ni internet. Si la frase no era de agenda
  // ("eventos en Santiago este finde"), el bot la deriva a web por su cuenta.
  route = 'google';
} else if (/\b(codex)\b/.test(text) || ARCHIVO.test(text) || /\b(codigo|script|python|bug|error|git|repositorio|systemd|docker|implementar|programar|configuracion tecnica)\b/.test(text)) {
  // Esta rama apuntaba a `codex` hasta el 19-09-2026, cuando Codex dejo de ser
  // ruta de lectura de vaults y quedo solo como motor de la ruta `web`. Se
  // REMAPEA a `claude` y no se borra: son preguntas tecnicas sobre los propios
  // archivos —systemd, docker, el codigo del bot— y necesitan un agente que los
  // lea. Borrar la rama las mandaria a PROPIO cuando la frase trae una palabra
  // propia y a `gpt` cuando no, que es el peor caso: Groq opinando sobre un
  // archivo que no puede ver. Sigue corriendo ANTES que PROPIO a proposito:
  // "arregla el error de systemd" no trae posesivo y igual hay que leer el nodo.
  // VOLVIO el 24-09-2026, por decision de Diego desde la pagina 🤖 de Cockpit,
  // pero SOLO para los perfiles con `codex` en sus rutas. El clasificador es uno
  // para todos los bots: mandarle `codex` a un perfil sin esa ruta lo degradaria
  // a `gpt` en el bot, o sea Groq opinando sobre archivos que no ve. Sin perfil
  // (una version vieja del bot) sigue siendo `claude`.
  route = PERFILES_CON_CODEX.has(perfil) ? 'codex' : 'claude';
} else {
  // El fallback NO puede ser claude. El conocimiento general es infinito y no se
  // puede enumerar; el dominio personal si, y es chico. Entonces se detecta lo
  // propio y todo lo demas va a la ruta general. Al reves (fallback a claude)
  // cada pregunta enciclopedica gastaba una llamada de agente para contestar
  // "eso no es mi alcance" — verificado el 12-09-2026 con "cuantos habitantes
  // hay en chile en 1993?". Los dos errores posibles se recuperan reformulando,
  // pero este es el que pasa seguido.
  // Al agregar un proyecto o un perfil nuevo, su nombre va en PROPIO.
  const PROPIO = /\b(mi|mis|mio|mia|mios|mias)\b|\b(nota|notas|archivo|archivos|documento|documentos|apunte|apuntes|vault|vaults|drive|carpeta|inbox|captura|capturas|memoria|frontmatter)\b|\b(proyecto|proyectos|arnes|arneses|licitacion|licitaciones|propuesta|propuestas|contrato|contratos|informe|minuta)\b|\b(pi5|gop|huerto|macetero|maceteros|cluster|quinque|rinco|nahuel|calama|cyd|camila|obsidian|syncthing|archify|nodo|pilar|jaime)\b/;
  // Datos que caducan -> ruta web. Quien busca depende del PERFIL: jaime va por
  // Codex (cuota de ChatGPT Plus) con Claude de respaldo; un perfil sin `codex`
  // en sus rutas va directo a Claude con su propia cuenta. Va DESPUES de PROPIO a
  // proposito: "la ultima nota de mi proyecto" tiene "ultima" pero se responde
  // leyendo el vault, no buscando en internet. Lo propio siempre gana.
// La lista se amplio el 13-09-2026 con terminos domesticos (manana, horario,
// abre/cierra, feriado, turno, semana) porque el error frecuente de un
// asistente de casa es "a que hora abre el mall manana", que se iba a Groq y
// contestaba de memoria. El costo de un falso positivo es una respuesta mas
// lenta pero con fuentes; el de un falso negativo es un dato viejo dicho con
// seguridad. La asimetria manda: ante la duda, buscar.
// Ampliada otra vez el 20-09-2026 con el vocabulario de cine y streaming, y hay
// dos lecciones que no se ven leyendo la lista: `pelicula` estaba pero `peliculas`
// NO —con \b el plural no caza, y la forma natural de preguntar es en plural—, y
// `actual` no cubre `actualidad`. Al sumar un termino, sumar su plural.
  const NECESITA_WEB = /\b(hoy|ayer|ahora|actual|actuales|actualmente|vigente|ultimo|ultima|ultimos|ultimas|reciente|recientes|noticia|noticias|precio|precios|dolar|uf|utm|clima|pronostico|cotizacion|resultado|gano|eleccion|elecciones|presidente|ministro|alcalde|manana|semana|horario|horarios|abre|abren|cierra|cierran|feriado|feriados|turno|cierre|cierres|atiende|atienden|abierto|abierta|restaurante|restaurantes|restoran|restorant|telefono|direccion|donde queda|llover|lluvia|viento|nieve|alerta|pasaje|pasajes|vuelo|vuelos|aeropuerto|metro|micro|trafico|peaje|farmacia|farmacias|supermercado|mall|tienda|sucursal|banco|hotel|delivery|entradas|cartelera|cine|peliculas?|estrenos?|series?|temporada|streaming|netflix|plataformas?|actualidad|concierto|partido|estadio|funcion|vence|vencimiento|tramite|tramites|patente|registro civil|permiso de circulacion|bitcoin|euro|ipc|bolsa|sueldo minimo|stock|disponible|oferta|ofertas|cuanto cuesta|cuanto vale|cuanto sale|20(2[5-9]|3[0-9]))\b/;
  if (PROPIO.test(text)) route = 'claude';
  else if (NECESITA_WEB.test(text)) route = 'web';
  else route = 'gpt';
}

// En modo auto se devuelve SIEMPRE la decision, nunca la respuesta final, aunque
// la ruta sea gpt y se pudiera resolver aca mismo. El bot espera {route} y con
// cualquier otra forma corta con "n8n devolvio una ruta no permitida" (pasado el
// 12-09-2026 con "Capital de uruguay"). Ese segundo viaje es lo que permite que
// el bot muestre "Ruta: X" y que Groq se invoque por un unico camino: source=gpt.
return [{ json: { mode: 'decision', payload: { route } } }];

// Groq responde con el esquema de OpenAI. Cualquier forma inesperada se
// convierte en un answer explicito: el bot NUNCA debe recibir un 200 vacio.
const r = $json ?? {};
const texto = r?.choices?.[0]?.message?.content;
const err = r?.error?.message;

let message;
if (typeof texto === 'string' && texto.trim()) {
  message = texto.trim();
} else if (err) {
  message = 'La ruta de conocimiento general fallo: ' + String(err).slice(0, 300);
} else {
  message = 'La ruta de conocimiento general no devolvio texto. Proba de nuevo o usa /claude.';
}

return [{ json: {
  kind: 'answer',
  message,
  sources: [],
  command_suggestion: '',
  command_context: ''
}}];
